package ru.neverland.mintespionage;
import java.util.*;
import static ru.neverland.mintespionage.intelligence.IntelEvidence.*;
public final class IntelEvidenceSmoke {
    static int checks;static void check(boolean good,String why){checks++;if(!good)throw new AssertionError(why);}static void denied(Runnable action,String why){try{action.run();}catch(IllegalArgumentException expected){check(true,why);return;}throw new AssertionError(why);}
    static Receipt receipt(UUID owner,UUID target,long at,Fact fact){return new Receipt(UUID.randomUUID(),UUID.randomUUID(),owner,target,"Цель","treasury",at,at+1000,true,true,true,"Город",Profile.of(2,1),List.of(fact),.7);}
    public static void main(String[] args){
        var profile=Profile.of(2,1);check(profile.roundingBasisPoints()==1900,"quality derived from network and counterintelligence, separate from mission chance");check(Profile.of(5,0).roundingBasisPoints()<Profile.of(0,0).roundingBasisPoints(),"network narrows rounding");check(Profile.of(2,4).roundingBasisPoints()>Profile.of(2,0).roundingBasisPoints(),"defense widens rounding");
        boolean bounds=true;var values=new long[]{0,1,9,10,999,1000,122999,Long.MAX_VALUE-1,Long.MAX_VALUE};for(long value:values){var fact=Fact.estimate("money","Казна","Towny.economy",100,value,2,profile,1000);bounds&=fact.lower()<=value&&fact.upper()>=value;}check(bounds,"all rounded bins include observed value even at long limits");
        var first=Fact.estimate("money","Казна","Towny.economy",100,123456,2,profile,1000);var adjacent=Fact.estimate("money","Казна","Towny.economy",100,123457,2,profile,1000);check(first.equals(adjacent),"rounding does not leak exact middle through symmetric endpoints");
        var unknown=Fact.unknown("money","Казна","Towny.economy",100,"Провайдер недоступен");check(unknown.display().equals("неизвестно")&&!unknown.numeric(),"unknown provider cannot become zero");var zero=Fact.exact("money","Казна","Towny.economy",100,0,2);check(zero.display().equals("0")&&zero.availability()==Availability.KNOWN,"known zero distinct from unknown");denied(()->Fact.estimate("money","Казна","source",0,-1,0,profile,1),"negative observations rejected");denied(()->Fact.words("invalid key","Текст","source",0,"text"),"keys bounded and validated");denied(()->Fact.words("text","Текст","source",0,"injected\nline"),"control sequence rejected");denied(()->Fact.words("text","Текст","source",0,"x".repeat(601)),"unbounded source strings refused");
        UUID owner=UUID.randomUUID(),target=UUID.randomUUID();var original=receipt(owner,target,100,first);var same=receipt(owner,target,200,Fact.estimate("money","Казна","Towny.economy",200,123500,2,profile,1000));var changed=receipt(owner,target,300,Fact.estimate("money","Казна","Towny.economy",300,999999,2,profile,1000));var unavailable=receipt(owner,target,400,Fact.unknown("money","Казна","Towny.economy",400,"Недоступно"));
        check(compare(original,List.of(same)).get(0).result()==Comparison.OVERLAPPING,"compatible range is not declared truthful");check(compare(original,List.of(same,changed)).get(0).result()==Comparison.CHANGED,"latest same source used and change not declared falsification");check(compare(original,List.of(changed,unavailable)).get(0).result()==Comparison.UNKNOWN,"latest unavailable source not replaced with older certainty");
        var foreign=receipt(UUID.randomUUID(),target,200,Fact.exact("money","Казна","Towny.economy",200,1,2));var otherTarget=receipt(owner,UUID.randomUUID(),200,Fact.exact("money","Казна","Towny.economy",200,1,2));check(compare(original,List.of(foreign,otherTarget)).get(0).result()==Comparison.NO_LATER_REPORT,"foreign city reports never compared");var wrongSource=receipt(owner,target,200,Fact.exact("money","Казна","other.source",200,1,2));check(compare(original,List.of(wrongSource)).get(0).result()==Comparison.NO_LATER_REPORT,"different source is not independent confirmation");check(compare(original,List.of(original)).get(0).result()==Comparison.NO_LATER_REPORT,"same observation never corroborates itself");
        var state=State.empty().put(original);check(state.put(original)==state,"exact captured mission idempotent");var reroll=new Receipt(original.mission(),original.report(),owner,target,"Цель","treasury",100,1100,false,false,true,"Город",profile,List.of(),.7);denied(()->state.put(reroll),"captured outcome cannot be rerolled");var applied=state.applied(original.mission());check(applied.applied().contains(original.mission())&&applied.applied(original.mission())==applied,"publication marker idempotent and distinct from capture");denied(()->state.applied(UUID.randomUUID()),"no publication marker without exact mission");denied(()->new Receipt(UUID.randomUUID(),UUID.randomUUID(),owner,target,"Цель","treasury",101,1100,true,false,false,"Город",profile,List.of(first),.7),"fact time must match observation time");check(original.expired(1100)&&!original.expired(1099),"staleness uses original frozen expiry");denied(()->new Profile(0,0,10000),"quality is not an arbitrary probability");
        System.out.println("IntelEvidenceSmoke PASS "+checks+" checks");
    }
}
